#!/usr/bin/env bash

set -euo pipefail

readonly repository_root="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
readonly tools_directory="$("${repository_root}/ops/scaleway/install-verification-tools.sh")"
export PATH="${tools_directory}:${PATH}"

temporary_directory="$(mktemp -d)"
trap 'rm -rf "${temporary_directory}"' EXIT

terraform fmt -check -recursive "${repository_root}/infrastructure/scaleway"

for root in \
  infrastructure/scaleway/bootstrap \
  infrastructure/scaleway/staging \
  infrastructure/scaleway/production; do
  root_key="${root//\//-}"
  TF_DATA_DIR="${temporary_directory}/${root_key}" \
    terraform -chdir="${repository_root}/${root}" init \
      -backend=false \
      -input=false \
      >/dev/null
  TF_DATA_DIR="${temporary_directory}/${root_key}" \
    terraform -chdir="${repository_root}/${root}" validate
done

trivy config \
  --exit-code 1 \
  --quiet \
  --severity HIGH,CRITICAL \
  "${repository_root}/infrastructure/scaleway"
import { Pool } from 'pg';

import { createNodePgPoolConfig } from '../../src/db/pg-connection-config';
import {
  postgresIntegrationChildEnvironment,
  requiredPostgresMajorVersion,
  resolvePostgresIntegrationEnvironment,
} from './postgres-integration-environment';
import { resetPublicSchema } from './reset-public-schema';

const runCommand = async (
  command: readonly string[],
  environment: Readonly<Record<string, string | undefined>>,
): Promise<void> => {
  const subprocess = Bun.spawn(command, {
    cwd: process.cwd(),
    env: { ...process.env, ...environment },
    stderr: 'inherit',
    stdin: 'inherit',
    stdout: 'inherit',
  });
  const exitCode = await subprocess.exited;
  if (exitCode !== 0) {
    throw new Error(`${command[0]} failed with exit code ${exitCode}`);
  }
};

const integrationEnvironment = await resolvePostgresIntegrationEnvironment();
const pool = new Pool(
  createNodePgPoolConfig({
    databaseUrl: integrationEnvironment.databaseUrl,
  }),
);

try {
  const versionResult = await pool.query<{ server_version_num: string }>(
    'SHOW server_version_num',
  );
  const versionNumber = Number.parseInt(
    versionResult.rows[0]?.server_version_num ?? '',
    10,
  );
  const majorVersion = Math.floor(versionNumber / 10_000);
  if (majorVersion !== requiredPostgresMajorVersion) {
    throw new Error(
      `PostgreSQL ${requiredPostgresMajorVersion} is required for integration tests`,
    );
  }
} finally {
  await pool.end();
}

await resetPublicSchema(integrationEnvironment);

const childEnvironment = {
  ...postgresIntegrationChildEnvironment(integrationEnvironment),
  LOCAL_DATABASE: 'true',
};
await runCommand(
  ['bunx', '--bun', 'drizzle-kit', 'push', '--force'],
  childEnvironment,
);
await runCommand(
  ['bunx', 'vitest', 'run', '--config', 'vitest.postgres.config.ts'],
  childEnvironment,
);
```

